"""No backend label on output cards.

With every backend (mock, llama.cpp, Ollama) the pages do not say where the generated text came from; the prototype
footer with the medical disclaimer stays on every page."""

from __future__ import annotations

import dataclasses

import pytest

from app.web.main import create_app
from conftest import Site

OLD_BANNERS = ("Placeholder output from the mock backend. Not generated by the language model.",
               "Generated by an Ollama-served model. Not the model used for the paper's results.")   # removed from the UI
FOOTER = "Not for real patient data. Not medical advice. Generated text may be inaccurate. Check doses and instructions with the care team."
# The safety notice is rendered in the footer of every page (no per-card disclaimer is rendered).
CARD_DISCLAIMER = FOOTER
ROLES = ("owner", "caregiver", "patient", "child")
# a page that shows generated text for each role: the dashboard, and the summaries tab that role can open
PAGES = {"owner": ("", "/summaries?tab=patient", "/summaries?tab=caregiver", "/summaries?tab=child"),
         "caregiver": ("", "/summaries?tab=patient", "/summaries?tab=caregiver", "/summaries?tab=child"),
         "patient": ("", "/summaries?tab=patient"),
         "child": ("", "/summaries?tab=child")}


def _no_source_label(text: str) -> bool:
    folded = text.casefold()
    return (not any(b in text for b in OLD_BANNERS) and "placeholder output" not in folded
            and "mock backend" not in folded and "ollama" not in folded and "language model" not in folded
            and "real model" not in folded)


def _site_with_backend(full, settings, ctx, runner, role, backend):
    app = create_app(dataclasses.replace(settings, backend=backend, job_timeout_seconds=1200),
                     ctx=ctx, runner=runner, start_worker=False)
    s = Site(app)
    assert s.login(full.users[role]["email"]).status_code == 303
    return s


@pytest.mark.parametrize("role", ROLES)
def test_no_label_for_any_role_in_mock_mode_and_the_footer_stays(full, role):
    assert full.p is not None
    for suffix in PAGES[role]:
        r = full.site[role].get(f"/p/{full.pid}{suffix}")
        assert r.status_code == 200, (role, suffix)
        assert _no_source_label(r.text), (role, suffix)
        assert CARD_DISCLAIMER in r.text and FOOTER in r.text.split("<footer", 1)[1], (role, suffix)


@pytest.mark.parametrize("backend", ("llama_cpp", "ollama"))
@pytest.mark.parametrize("role", ROLES)
def test_no_label_for_any_role_with_the_real_backends(full, settings, ctx, runner, role, backend):
    """Same database, configured with another backend (these requests load no model and make no Ollama call)."""
    s = _site_with_backend(full, settings, ctx, runner, role, backend)
    for suffix in PAGES[role]:
        r = s.get(f"/p/{full.pid}{suffix}")
        assert r.status_code == 200, (role, suffix)
        assert _no_source_label(r.text), (role, suffix)
        assert "paper's results" not in r.text and "paper&#39;s results" not in r.text, (role, suffix)
        assert CARD_DISCLAIMER in r.text and FOOTER in r.text.split("<footer", 1)[1], (role, suffix)


@pytest.mark.parametrize("backend", ("mock", "ollama"))
def test_no_other_page_names_the_backend(full, settings, ctx, runner, backend):
    s = _site_with_backend(full, settings, ctx, runner, "owner", backend)
    for url in ("/", "/profiles", "/settings", f"/p/{full.pid}", f"/p/{full.pid}/notes", f"/p/{full.pid}/circle",
                f"/p/{full.pid}/info"):
        r = s.get(url)
        assert _no_source_label(r.text), url
        assert FOOTER in r.text.split("<footer", 1)[1], url
